import{z as p,x as B,o as l,c as d,q as E,j as r,D as e,d as t,s as n,S as i,b as s}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"数据中心 Clos / 胖树","description":"","frontmatter":{"title":"数据中心 Clos / 胖树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/datacenter-clos.md","filePath":"cs/datacenter-clos.md","lastUpdated":1791413859000}'),A={name:"cs/datacenter-clos.md"};function c(C,a,h,P,m,f){const o=B("Mermaid");return l(),d("div",null,[a[2]||(a[2]=E('<h1 id="数据中心-clos-胖树" tabindex="-1">数据中心 Clos / 胖树 <a class="header-anchor" href="#数据中心-clos-胖树" aria-label="Permalink to &quot;数据中心 Clos / 胖树&quot;">​</a></h1><div class="epigraph"><p>叶子–脊线全互联把东西向带宽做成多级 Clos；ECMP 把流洒在多条等代价边上，取代大二层生成树。</p><footer>—— 据 Clos, A Study of Non-blocking Switching Networks, BSTJ 1953；Al-Fares et al., SIGCOMM 2008 胖树整理</footer></div><p><a href="/cs/output-queue-hol">交换机 HOL</a> 与 <a href="/cs/ecmp-hashing">ECMP</a> 已备好。<a href="/cs/p4-programmable">上一课</a> 不改拓扑。缺口是<strong>数据中心怎么连</strong>：leaf-spine、过订购比、L3 到叶子。本课不把 incast 扇入写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>接入–汇聚–核心树在东西向拥挤，STP 还要阻塞边。胖树/Clos：每叶子连所有脊，脊再可选超脊。带宽由「叶子上联数 × 口速」决定，过订购是刻意的经济。转发：每叶子一个子网，主机默认网关在叶子（IRB/EVPN），中间纯 L3 ECMP，无 STP 大域。VXLAN 覆盖跑在这张 IP 网上。</p><p><span class="marginnote">过订购用数字算：一片叶子下面接 48 个 10G 主机口，上联到脊只有 4 条 10G，过订购比就是 48:4 = 12:1。它赌的是「不是所有人同时满发」；若 48 台机器同时往外拷数据，每台平均只分到不到 1G 的东西向带宽，排队不可避免。</span></p><p>不要把 Clos 写成无阻塞的数学保证：流量矩阵一偏，脊仍可满。</p><p><span class="marginnote">Clos 原是电话交叉。Al-Fares 把胖树搬到以太网。本课不点名某云的内部名。</span></p><h3 id="东西向用-ecmp" tabindex="-1">东西向用 ECMP <a class="header-anchor" href="#东西向用-ecmp" aria-label="Permalink to &quot;东西向用 ECMP&quot;">​</a></h3><p>leaf-spine 多条等代价，大 STP 退出。过订购是经济，流量一偏脊仍满。故障重哈希会短暂乱序。</p><p><span class="marginnote">ECMP（等价多路径）可以想成收费站并开的一排等长车道：路由器把去往同一目的地的每条流按哈希固定分给某条路，流内不换道（免得包乱序），不同流之间摊匀负载；哪条车道先满，取决于流量分得匀不匀。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：leaf 与 spine 全网格。对照校园三层：这里每跳都 ECMP。LACP 可把多口当一条上联，但叶子到脊更常用独立 ECMP 边。</p>',13)),(l(),r(i,null,{default:e(()=>[n(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E4%B8%BB%E6%9C%BA%22%5D%20--%3E%20L%5B%22%E5%8F%B6%E5%AD%90%22%5D%0A%20%20L%20--%3E%20S1%5B%22%E8%84%8A%22%5D%0A%20%20L%20--%3E%20S2%5B%22%E8%84%8A%22%5D%0A%20%20S1%20--%3E%20L2%5B%22%E5%8F%A6%E4%B8%80%E5%8F%B6%E5%AD%90%22%5D%0A%20%20S2%20--%3E%20L2%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[t("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"TE 在数据中心常简化为 ECMP + 尽量对称布线；极化仍在。BGP 可作 IGP（每盒一个 ASN 或私有 AS），收敛与策略比 OSPF 更熟——这是运营选择。5G 核心 UPF 也可落在 Clos 上，无线切片不改机房拓扑。",-1)),a[5]||(a[5]=s("p",null,"一条脊挂掉之后，网络是怎么收敛的：",-1)),(l(),r(i,null,{default:e(()=>[n(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%B8%80%E6%9D%A1%E8%84%8A%E4%BA%A4%E6%8D%A2%E6%9C%BA%E6%95%85%E9%9A%9C%22%5D%20--%3E%20B%5B%22%E5%8F%B6%E5%AD%90%E6%94%B6%E4%B8%8D%E5%88%B0%E5%AE%83%E7%9A%84%E8%B7%AF%E7%94%B1%22%5D%0A%20%20B%20--%3E%20C%5B%22BGP%20%E6%92%A4%E9%94%80%E8%BF%99%E6%9D%A1%E8%B7%AF%E5%BE%84%22%5D%0A%20%20C%20--%3E%20D%5B%22ECMP%20%E4%B8%8B%E4%B8%80%E8%B7%B3%E9%9B%86%E5%90%88%E6%94%B6%E7%BC%A9%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%8F%97%E5%BD%B1%E5%93%8D%E7%9A%84%E6%B5%81%E9%87%8D%E6%96%B0%E5%93%88%E5%B8%8C%E5%88%B0%E5%89%A9%E4%BD%99%E8%84%8A%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%8D%A2%E4%BA%86%E8%B7%AF%E5%BE%84%E7%9A%84%E6%B5%81%E7%9F%AD%E6%9A%82%E4%B9%B1%E5%BA%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<p>故障：一条脊挂了，哈希重映射，短暂乱序，与 LACP 成员 down 同类。</p><p><span class="marginnote">初学者容易把「无阻塞 Clos」理解成永不拥塞。实际上无阻塞只保证拓扑里存在足够多的可走路径；流量矩阵一偏——比如十台服务器同时拷同一台——共享的脊照样打满、排队甚至丢包，拓扑救不了偏斜的流量。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Jupiter 一类专有细节。incast 是下一课。后课默认：东西向用 Clos + L3 ECMP，大 STP 退出。</p><p>光模块与 100G lane 决定实际能铺多少脊。</p><p>下一课<a href="/cs/incast">incast</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>leaf-spine Clos 提供多条等代价东西向路径。</li><li>过订购是容量规划，不是协议字段。</li><li>用 ECMP 替代阻塞冗余边。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Clos, 1953；Al-Fares et al., 2008。</li></ul>',8))])}const S=p(A,[["render",c]]);export{D as __pageData,S as default};
